	@Test
	void logsSlowTupleQueryToConfiguredFile(@TempDir Path tempDir) throws Exception {
		requireSecureDirectoryStreams(tempDir);
		Path logFile = tempDir.resolve("slow-query.log");
		TestMemoryStore store = new TestMemoryStore();
		store.setDataDir(tempDir.toFile());
		configureSlowQueryThreshold(store, 1L);
		configureSlowQueryLogFile(store, "slow-query.log");

		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(RDF.TYPE, RDF.TYPE, RDF.TYPE);
			}

			store.setCurrentTimeMillis(1_000L);

			try (RepositoryConnection connection = repository.getConnection()) {
				String queryText = "SELECT * WHERE { ?s ?p ?o }";
				try (TupleQueryResult result = connection.prepareTupleQuery(queryText).evaluate()) {
					assertThat(result.hasNext()).isTrue();
					store.setCurrentTimeMillis(3_000L);
				}
			}

			assertThat(logFile).exists();
			String logOutput = Files.readString(logFile);
			assertThat(logOutput)
					.contains("SELECT * WHERE { ?s ?p ?o }")
					.contains("Unoptimized")
					.contains("Optimized")
					.contains("Rendered optimized query");
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void logsSlowAskQueryToFallbackLogger() throws Exception {
		TestMemoryStore store = new TestMemoryStore();
		configureSlowQueryThreshold(store, 1L);
		store.queueTimestampMillis(1_000L, 3_000L);

		Logger logger = (Logger) org.slf4j.LoggerFactory.getLogger("org.eclipse.rdf4j.sail.slowquery");
		Level previousLevel = logger.getLevel();
		CapturingAppender appender = new CapturingAppender();
		appender.setContext((LoggerContext) org.slf4j.LoggerFactory.getILoggerFactory());
		logger.addAppender(appender);
		appender.start();
		logger.setLevel(Level.WARN);

		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(RDF.TYPE, RDF.TYPE, RDF.TYPE);
			}

			try (RepositoryConnection connection = repository.getConnection()) {
				boolean result = connection.prepareBooleanQuery("ASK WHERE { ?s ?p ?o }").evaluate();
				assertThat(result).isTrue();
			}
		} finally {
			repository.shutDown();
			logger.detachAppender(appender);
			appender.stop();
			logger.setLevel(previousLevel);
		}

		assertThat(appender.messages(Level.WARN))
				.singleElement()
				.satisfies(message -> assertThat(message)
						.contains("ASK WHERE { ?s ?p ?o }")
						.contains("queryType=BOOLEAN"));
	}

